/* @autogenerated */
package net.civeira.phylax.common.infrastructure.config;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.Optional;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class IsolatedConfigLoaderUnitTest {
  private static final String SAMPLE = "isolated-config/sample.yaml";

  @TempDir
  Path external;

  @Test
  void testReadValuesFromTheClasspath() {
    IsolatedConfig config = loader(List.of(), Map.of()).load(SAMPLE);

    assertTrue(config.exists());
    assertEquals(Optional.of("root"), config.getConfig("root.name"));
    assertEquals(3, config.getRequiredConfig("root.attempts", Integer.class));
  }

  @Test
  void testEmptyExpressionIsMissing() {
    IsolatedConfig config = loader(List.of(), Map.of()).load(SAMPLE);

    assertEquals(Optional.empty(), config.getConfig("root.password"));
    NoSuchElementException ex =
        assertThrows(NoSuchElementException.class, () -> config.getRequiredConfig("root.password"));
    assertTrue(ex.getMessage().contains("root.password"));
  }

  @Test
  void testEnvironmentResolvesExpressions() {
    IsolatedConfig config =
        loader(List.of(), Map.of("SAMPLE_ROOT_PASSWORD", "from-env")).load(SAMPLE);

    assertEquals(Optional.of("from-env"), config.getConfig("root.password"));
  }

  @Test
  void testEnvironmentOverridesKeys() {
    IsolatedConfig config = loader(List.of(), Map.of("CLIENT_SECRET", "env-secret")).load(SAMPLE);

    assertEquals(Optional.of("env-secret"), config.getConfig("client.secret"));
  }

  @Test
  void testActiveProfileValues() {
    IsolatedConfig config = loader(List.of("dev"), Map.of()).load(SAMPLE);

    assertEquals(Optional.of("dev-password"), config.getConfig("root.password"));
  }

  @Test
  void testExternalFileOverridesTheClasspath() throws IOException {
    Path file = external.resolve(SAMPLE);
    Files.createDirectories(file.getParent());
    Files.writeString(file, "client:\n  secret: external-secret\n");

    IsolatedConfig config = loader(List.of(), Map.of()).load(SAMPLE);

    assertEquals(Optional.of("external-secret"), config.getConfig("client.secret"));
    assertEquals(Optional.of("root"), config.getConfig("root.name"));
  }

  @Test
  void testMissingFileIsEmpty() {
    IsolatedConfig config = loader(List.of(), Map.of()).load("isolated-config/missing.yaml");

    assertFalse(config.exists());
    assertEquals(Optional.empty(), config.getConfig("root.name"));
  }

  @Test
  void testDotEnvResolvesExpressions() throws IOException {
    Path dotEnv = external.resolve(".env");
    Files.writeString(dotEnv, "# comment\nSAMPLE_ROOT_PASSWORD=from-dotenv\n");

    IsolatedConfig config =
        loader(List.of(), IsolatedConfigLoader.environment(dotEnv, Map.of())).load(SAMPLE);

    assertEquals(Optional.of("from-dotenv"), config.getConfig("root.password"));
  }

  @Test
  void testEnvironmentOverridesDotEnv() throws IOException {
    Path dotEnv = external.resolve(".env");
    Files.writeString(dotEnv, "SAMPLE_ROOT_PASSWORD=from-dotenv\n");

    IsolatedConfig config = loader(List.of(),
        IsolatedConfigLoader.environment(dotEnv, Map.of("SAMPLE_ROOT_PASSWORD", "from-env")))
            .load(SAMPLE);

    assertEquals(Optional.of("from-env"), config.getConfig("root.password"));
  }

  @Test
  void testMissingDotEnvKeepsTheEnvironment() {
    Map<String, String> environment = IsolatedConfigLoader.environment(external.resolve(".env"),
        Map.of("SAMPLE_ROOT_PASSWORD", "from-env"));

    assertEquals(Map.of("SAMPLE_ROOT_PASSWORD", "from-env"), environment);
  }

  private IsolatedConfigLoader loader(List<String> profiles, Map<String, String> environment) {
    return new IsolatedConfigLoader(external, profiles, environment);
  }
}
